/*
 * Book notes. Two layers per book: the takeaways (what you get at a glance)
 * and `deep` (the full-detail view, opened on demand).
 *
 * Quotes are kept short and only included where the wording is well known and
 * verifiable. Everything else is paraphrase, so nothing is misattributed.
 */

export interface BookSection { h: string; body: string }

export interface Book {
  id: string;
  title: string;
  author: string;
  tag: string;                    // one-line positioning
  category: 'people' | 'habits' | 'money';
  takeaways: [string, string][];  // the quick view
  thesis: string;                 // the whole argument in a paragraph
  deep: BookSection[];            // the detail view
  quotes?: string[];
  criticism: string;              // honest limitations — always present
  verdict: string;                // read / skim / skip, and for whom
  doThisWeek: string[];
}

